const decks=()=>[...new Set(state.cards.filter(c=>!c.lessonPending).map(c=>c.deck))];
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{storageOK=false;toast('Saqlash uchun brauzer xotirasi yetarli emas. Zaxira nusxasini yuklab oling.');}updateHeader();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function updateHeader(){const user=classroomUI.user(),role=user?.role==='teacher'?'O‘qituvchi maydoni':user?.role==='student'?'O‘quvchi maydoni':'Lexora Academy';if($('#role-label'))$('#role-label').textContent=role;$('.space-label').textContent=role.toUpperCase();$('#xp').hidden=classroomUI.teacher();$('#streak').hidden=classroomUI.teacher();$('#xp').innerHTML=icon('chart')+` ${state.xp} XP`;$('#streak').innerHTML=icon('course')+` ${streak(state.log)} kun`;$('#profile-name').innerHTML=`${e(user?.name||state.name)}<small>${user?.role==='teacher'?'O‘qituvchi':user?.role==='student'?'O‘quvchi':'Ro‘yxatdan o‘tish'}</small>`;document.querySelectorAll('.profile-avatar,.header-avatar').forEach(el=>el.textContent=state.name.slice(0,1).toUpperCase());}
function heading(label,title,sub,right=''){return `<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${sub}</p></div>${right}</div>`;}
function stat(icon,value,label){return `<div class="stat"><span class="stat-icon">${icon}</span><div class="num">${value}<small>${label}</small></div></div>`;}
function deckRows(){return decks().map((name,i)=>{const cards=state.cards.filter(c=>c.deck===name),n=cards.filter(c=>c.due<=Date.now()).length,pct=cards.length?Math.round(cards.filter(c=>c.reps>0).length/cards.length*100):0;return `<div class="deck"><span class="deck-icon">${['▤','Aa','✦'][i%3]}</span><div class="deck-copy"><h3>${e(name)}</h3><small>${cards.length} so‘z · ${n} ta takrorlash uchun</small><div class="progress"><span style="width:${pct}%"></span></div></div><button class="btn" data-study="${e(name)}">O‘rganish ↗</button></div>`;}).join('')||'<div class="empty">Topshirilgan darslarning so‘zlari shu yerda ko‘rinadi.</div>';}
function practiceCards(){const n=due().length,remaining=lessons.filter(l=>!state.completed.includes(l.id)).length;const cards=[
 {icon:'book',color:'blue',status:n?'Takrorlash vaqti':'Navbat yakunlangan',title:'Lug‘atni mustahkamlang',sub:'O‘zbekcha → Inglizcha',copy:n?`${n} ta so‘z takrorlash uchun tayyor.`:'Keyingi takrorlash vaqti kelganda davom eting.',meta:'Intervalli takrorlash',action:n?'data-action="study"':'data-route="vocab"',label:n?'Boshlash':'Lug‘atni ochish'},
 {icon:'mic',color:'purple',status:'Speaking · 3 format',title:'Fikringizni ayting',sub:'IELTS & kundalik mavzular',copy:'Javobingizni ovozga yozib, qayta tinglang.',meta:'1–2 daqiqa',action:'data-route="speaking"',label:'Mashq qilish'},
 {icon:'edit',color:'amber',status:'Takrorlashdan keyin',title:'Yakuniy so‘zlar testi',sub:'Variantlar + imlo',copy:'Hozir takrorlagan so‘zlaringizdan test topshiring.',meta:'Bir jarayonda',action:'data-route="study"',label:'Davom etish'},
 {icon:'course',color:'mint',status:remaining?'Qisqa dars':'Darslar tugallangan',title:'O‘rganishni o‘rganing',sub:'Kontekst, collocation va SRS',copy:remaining?`${remaining} ta qisqa dars sizni kutyapti.`:'Bilimingizni yangilash uchun qayta ko‘ring.',meta:'2–4 daqiqa',action:'data-route="courses"',label:'Darsni ochish'}
 ];return `<div class="task-grid">${cards.map(c=>`<article class="task-card"><div class="task-top"><span class="task-icon ${c.color}">${icon(c.icon)}</span><span class="task-status">${c.status}</span></div><h3>${c.title}</h3><p>${c.sub}<br>${c.copy}</p><div class="task-footer"><span>${c.meta}</span><button ${c.action}>${c.label} <span aria-hidden="true">→</span></button></div></article>`).join('')}</div>`;}
function tasks(){return heading('O‘QUV MAYDONI','Topshiriqlar','Lug‘at, yozma va og‘zaki mashqlarni bir joyda davom ettiring.')+classroomUI.lessonPanel()+practiceCards();}
function home(){const n=due().length;return `<div class="workspace-title"><div><span class="eyebrow">YOUR LEARNING SPACE</span><h1>Salom, ${e(state.name)}<span class="coral-dot">.</span></h1><p>Bugun qaysi ko‘nikmangizni rivojlantiramiz?</p></div><span class="workspace-date">${shortDate(new Date())}</span></div><div class="workspace-summary"><div><b>${streak(state.log)}</b><span>kunlik muntazamlik</span></div><div><b>${n}</b><span>takrorlash uchun so‘z</span></div><div><b>${today()}</b><span>bugungi takrorlash</span></div><a href="#analytics">Natijalarim ↗</a></div><section class="learning-banner"><div><span class="eyebrow">KICHIK QADAM. ANIQ NATIJA.</span><h2>Tilni yodlamang.<br>Undan foydalaning.</h2><p>So‘zlarni eslang, fikringizni yozing va ovoz chiqarib ayting. Mashqlaringiz shu yerdan boshlanadi.</p><a class="btn primary" href="#tasks">Darslarimni ochish ↗</a></div><div class="banner-index" aria-hidden="true"><span>READ</span><span>LISTEN</span><span>WRITE</span><span>SPEAK<span class="coral-dot">.</span></span></div></section><section class="desk-section"><div class="section-heading"><h2>Mashq maydonlari</h2><span class="help-text">O‘z sur’atingizda davom eting</span></div><div class="skill-directory">${[['vocab','01','Vocabulary','So‘zlarni eslash va SRS','Aa'],['speaking','02','Speaking','Ovoz yozish va qayta tinglash','↗'],['reading','03','Reading','Matn va tushunish testi','≡'],['listening','04','Listening','Tinglash va tafsilotlar','⌁'],['writing','05','Writing','Insho va shaxsiy qoralama','✎'],['groups','06','Mening guruhim','Ustoz bergan darslar','▤']].map(([id,num,title,copy,mark])=>`<a href="#${id}" class="skill-tile"><span class="tile-number">${num}</span><span class="tile-mark" aria-hidden="true">${mark}</span><h3>${title}</h3><p>${copy}</p><span class="tile-arrow">↗</span></a>`).join('')}</div></section>${classroomUI.lessonPanel()}`;}
function previousHome(){const n=due().length,pct=Math.min(100,today()/state.goal*100),week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d;});return `<div class="greeting"><div><h1>Salom, ${e(state.name)}!</h1><p>Bugungi kichik qadam — katta maqsadingiz sari.</p></div><span class="date">${shortDate(new Date())}</span></div>${classroomUI.lessonPanel()}<div class="dashboard"><div><section class="hero"><span class="hero-eyebrow">◎ &nbsp; BUGUNGI MAQSAD</span><h2>Bugungi mashqlaringiz.<br>Ertangi natijangiz.</h2><p>${n?`${n} ta so‘z takrorlashni kutyapti.`:'Bugungi takrorlash navbati yakunlangan.'}<br>${n?'Avval eslang, keyin javobni tekshiring.':'Speaking yoki qisqa dars bilan davom eting.'}</p><button class="primary" ${n?'data-action="study"':'data-route="speaking"'}>${n?'Mashqni boshlash':'Speaking’ga o‘tish'} <span aria-hidden="true">→</span></button><div class="hero-art" aria-hidden="true"><div class="art-back"></div><div class="art-card"><div class="art-card-head"><span></span><span>VOCABULARY</span><span>01</span></div><strong>Aa<span>.</span></strong><div class="art-card-line"></div><div class="art-card-line short"></div><div class="art-card-bottom"><span>LEARN. USE. REPEAT.</span><span aria-hidden="true">↗</span></div></div><div class="art-audio"><span aria-hidden="true">♪</span><div class="audio-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><div class="art-check"><span aria-hidden="true">✓</span></div></div><div class="hero-footer">◷ &nbsp; O‘z sur’atingizda <span>·</span> 4 xil mashq</div></section><section class="desk-section"><div class="section-heading"><h2>Bugungi mashqlar</h2><a href="#tasks">Barchasi →</a></div>${practiceCards()}</section><section class="desk-section"><div class="section-heading"><h2>So‘z to‘plamlari</h2><a href="#vocab">Lug‘atni ochish →</a></div><div class="panel library-list">${deckRows()}</div></section><section class="growth"><span class="task-icon mint">${icon('chart')}</span><div><h3>Muntazamlik — sizning kuchli tomoningiz.</h3><p>Har bir mashqingiz natijalarda aks etadi.</p></div><button class="text-btn" data-route="analytics" aria-label="Natijalarni ko‘rish">→</button></section></div><aside class="right-column"><section class="right-panel"><div class="section-heading"><h2>Bugungi reja</h2><button class="text-btn" data-route="settings" aria-label="Kunlik maqsadni sozlash">◎</button></div><div class="goal-ring" style="--goal:${pct}%"><div><strong>${today()}<span> / ${state.goal}</span></strong><small>kartochka takrorlandi</small></div></div><p class="daily-copy">${today()>=state.goal?'Kunlik maqsad bajarildi!':`Yaxshi odat kichik qadamdan boshlanadi.<br>Bugun yana ${Math.max(0,state.goal-today())} ta takrorlash qoldi.`}</p><div class="week">${week.map(d=>`<div class="day ${state.log[dateKey(d)]?'done':''}">${uzDays[d.getDay()]}<span>${state.log[dateKey(d)]?'✓':d.getDate()}</span></div>`).join('')}</div></section><section class="right-panel group-panel"><div class="section-heading"><h2>Mening guruhim</h2>${icon('group')}</div><div class="group-empty-icon">${icon('group')}</div><h3>Birgalikda o‘rganish</h3><p>Guruhingizning darslari, so‘z to‘plamlari va topshiriqlarini oching.</p><button class="btn" data-route="telegram">Guruhlarim →</button></section><section class="right-panel"><span class="eyebrow">SIZNING O‘SISHINGIZ</span><div class="small-metrics"><div>${streak(state.log)}<small>kun ketma-ket</small></div><div>${state.cards.length}<small>so‘z kutubxonada</small></div></div><a class="summary-link" href="#analytics">Natijalarni ko‘rish →</a></section></aside></div>`;}

function vocab(){return heading('','Lug‘at','Bugungi so‘zlaringiz. Birma-bir, o‘z sur’atingizda.')+`<section class="revision-start panel"><div><h2>${classroomUI.teacher()?'Mashqni namoyish qilish':'Bugungi takrorlash'}</h2><p>${classroomUI.teacher()?'Guruhlaringizdagi so‘zlarni o‘quvchiga ko‘rsatib bering. Natijalar reytingga kirmaydi.':'Avval eslang, keyin javobni oching. Yakunda qisqa test kutadi.'}</p></div>${btn(classroomUI.teacher()?'Mashqni sinash':'Boshlash','study','primary')}<div id="revision-overview" class="revision-overview" aria-live="polite">Navbat yuklanmoqda…</div></section>${classroomUI.lessonPanel()}<section class="panel"><h2>Decklar</h2>${deckRows()}</section><details class="panel word-browser"><summary>Barcha so‘zlarni ko‘rish va qidirish</summary><div class="toolbar"><input id="search" type="search" placeholder="So‘z yoki tarjima…" value="${e(search)}" aria-label="So‘z qidirish"><select id="deck-filter" aria-label="To‘plam"><option value="">Barcha decklar</option>${decks().map(d=>`<option ${d===deckFilter?'selected':''}>${e(d)}</option>`).join('')}</select></div><div class="table-wrap" id="word-table">${wordTable()}</div></details><section class="panel competition-panel"><h2>Haftalik musobaqa</h2><p>Guruhingiz bilan birga o‘sing. Bir xil ball — bir xil o‘rin.</p><div id="competition" aria-live="polite">Reyting yuklanmoqda…</div><details><summary>Ball qanday beriladi?</summary><p>Kuniga 10 / 25 / 50 ta turli so‘zni takrorlash: har bosqichga 10 XP (kunlik jami 30). Dars testidan kamida 80%: 20 XP, to‘liq to‘g‘ri topshirilsa yana 10 XP. Dars uchun bir marta. Namoyish va qayta urinishlar qo‘shimcha ball bermaydi.</p></details></section>`;}
function wordTable(){const cards=state.cards.filter(c=>!c.lessonPending&&(!deckFilter||c.deck===deckFilter)&&normalize(c.word+' '+c.translation).includes(normalize(search)));return `<table><thead><tr><th>SO‘Z / IBORA</th><th>TARJIMA</th><th>TO‘PLAM</th><th>HOLAT</th><th>AMALLAR</th></tr></thead><tbody>${cards.map(c=>`<tr><td>${e(c.word)} <span class="tag">${e(c.level)}</span><small>${e(c.example)}</small></td><td>${e(c.translation)}</td><td>${e(c.deck)}</td><td><span class="tag ${c.due>Date.now()?'green':''}">${c.due>Date.now()?new Date(c.due).toLocaleDateString('uz-UZ'):c.reviews?'Takrorlash':'Yangi'}</span></td><td><button class="icon-btn" data-audio="${e(c.word)}" aria-label="Talaffuz">♫</button></td></tr>`).join('')}</tbody></table>${cards.length?'':`<div class="empty">Deck hozircha bo‘sh. Guruhingizdagi darsni kamida 80% bilan topshiring.</div>`}`;}
function addModal(id){toast('So‘zlarni faqat o‘qituvchi guruh ichida qo‘shadi.');return; const c=state.cards.find(x=>x.id===id)||{word:'',translation:'',example:'',deck:deckFilter||decks()[0]||'Mening so‘zlarim',level:'B2'};openModal(id?'So‘zni tahrirlash':'Yangi so‘z qo‘shish',`<form id="word-form" class="form-grid"><label>Inglizcha so‘z yoki ibora<input name="word" required maxlength="120" value="${e(c.word)}" autofocus></label><label>O‘zbekcha tarjima<input name="translation" required maxlength="500" value="${e(c.translation)}"></label><label>To‘plam<input name="deck" required maxlength="80" list="deck-names" value="${e(c.deck)}"><datalist id="deck-names">${decks().map(d=>`<option value="${e(d)}">`).join('')}</datalist></label><label>Daraja<select name="level">${['A1','A2','B1','B2','C1','C2'].map(l=>`<option ${l===c.level?'selected':''}>${l}</option>`).join('')}</select></label><label class="full">Misol jumla (ixtiyoriy)<input name="example" maxlength="1000" value="${e(c.example)}"></label><label>IPA (ixtiyoriy)<input name="ipa" maxlength="120" placeholder="/rɪˈzɪliənt/" value="${e(c.ipa||'')}"></label><label>So‘z turkumi<input name="pos" maxlength="60" placeholder="adjective" value="${e(c.pos||'')}"></label><label class="full">Misolning o‘zbekcha tarjimasi<input name="exampleUz" maxlength="1000" value="${e(c.exampleUz||'')}"></label><label class="full">Sinonimlar<input name="synonyms" maxlength="500" placeholder="strong, adaptable" value="${e(c.synonyms||'')}"></label><label class="full">Collocation / birikmalar<input name="collocations" maxlength="1000" placeholder="remain resilient; resilient economy" value="${e(c.collocations||'')}"></label><div id="form-error" class="error full"></div><div class="buttons full"><button class="btn primary">Saqlash</button><button class="btn" type="button" data-action="close">Bekor qilish</button></div></form>`);$('#word-form').onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));for(const k in data)data[k]=data[k].trim();if(!data.word||!data.translation||!data.deck)return; if(state.cards.some(x=>x.id!==id&&normalize(x.word)===normalize(data.word)&&normalize(x.deck)===normalize(data.deck))){$('#form-error').textContent='Bu so‘z ushbu to‘plamda allaqachon mavjud.';return;}if(id)Object.assign(c,data);else state.cards.push({...data,id:uid(),reps:0,reviews:0,due:0,ease:2.5,interval:0});save();$('#modal').close();render();toast('So‘z saqlandi');};}
function deckModal(){toast('Decklarni o‘qituvchi guruh ichida yaratadi.');return; openModal('Yangi to‘plam yaratish',`<form id="deck-form"><label>To‘plam nomi<input name="deck" required maxlength="80" placeholder="Destination B2 — Unit 1" style="width:100%;margin:10px 0 18px"></label><div id="deck-error" class="error"></div><button class="btn primary">Yaratish</button></form>`);$('#deck-form').onsubmit=ev=>{ev.preventDefault();const name=String(new FormData(ev.target).get('deck')).trim();if(!name)return;if(decks().some(d=>normalize(d)===normalize(name))){$('#deck-error').textContent='Bu nomli to‘plam mavjud.';return;}state.deckNames=[...(state.deckNames||[]),name];save();$('#modal').close();deckFilter=name;search='';location.hash='vocab';if(route==='vocab')render();toast('To‘plam yaratildi. Endi so‘z qo‘shing yoki import qiling.');};}
function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}
function importModal(){toast('Import o‘qituvchi kabinetida, guruhning Decklar bo‘limida.');return;
 openModal('So‘zlarni import qilish',`<p>Har qatorda <b>inglizcha ; o‘zbekcha ; misol</b> yozing. Excel’dan ikki ustunni ham nusxalash mumkin.</p><form id="import-form"><label>To‘plam nomi<input name="deck" value="${e(deckFilter||'Mening so‘zlarim')}" required maxlength="80" style="width:100%;margin:8px 0 16px"></label><label>So‘zlar<textarea name="text" placeholder="resilient ; bardoshli ; She is resilient.&#10;achieve ; erishmoq" required maxlength="200000"></textarea></label><label style="display:block;margin-top:15px">Yoki fayldan oching (.txt, .tsv, ; bilan ajratilgan .csv)<input type="file" id="import-file" accept=".txt,.tsv,.csv" style="width:100%"></label><div class="error" id="import-error" role="alert"></div><div class="buttons"><button class="btn primary">Ro‘yxatni tekshirish →</button><button class="btn" type="button" data-action="close">Bekor qilish</button></div></form><div id="import-preview"></div><p style="font-size:10px;margin-top:20px">Import tayyor so‘z va tarjimalarni oladi. AI tarjimasi hali ulanmagan.</p>`);
 const form=$('#import-form'),preview=$('#import-preview');let pending=[];
 const invalidate=()=>{pending=[];preview.innerHTML='';$('#import-error').textContent='';};
 form.addEventListener('input',invalidate);
 $('#import-file').onchange=async ev=>{invalidate();const f=ev.target.files[0];if(!f)return;if(f.size>200000){$('#import-error').textContent='Fayl 200 KB dan kichik bo‘lishi kerak.';return;}form.elements.text.value=await f.text();invalidate();};
 form.onsubmit=ev=>{ev.preventDefault();invalidate();const data=new FormData(form),deck=String(data.get('deck')).trim(),{rows,errors}=parseWords(String(data.get('text')),deck);if(!deck)return;
  if(errors.length){$('#import-error').textContent=`${errors.slice(0,20).join(', ')}-qatorni tekshiring: so‘z va tarjima kerak. Hech narsa import qilinmadi.`;return;}
  if(!rows.length){$('#import-error').textContent='Import qilish uchun kamida bitta so‘z kiriting.';return;}
  if(rows.length>1000){$('#import-error').textContent='Bir marta 1000 tagacha so‘z import qilish mumkin.';return;}
  const seen=new Set(state.cards.map(c=>normalize(c.deck)+'\n'+normalize(c.word)));let skipped=0;
  for(const row of rows){const key=normalize(row.deck)+'\n'+normalize(row.word);if(seen.has(key)){skipped++;continue;}seen.add(key);pending.push(row);}
  preview.innerHTML=`<div class="notice"><b>${pending.length} ta yangi so‘z</b> · ${skipped} ta takroriy so‘z o‘tkaziladi.<br>Saqlashdan oldin tarjimalarni tekshiring.</div>${pending.length?`<div class="table-wrap" style="border:1px solid var(--line);max-height:270px"><table style="min-width:450px"><thead><tr><th>INGLIZCHA</th><th>O‘ZBEKCHA</th></tr></thead><tbody>${pending.slice(0,20).map(c=>`<tr><td>${e(c.word)}</td><td>${e(c.translation)}</td></tr>`).join('')}</tbody></table></div>${pending.length>20?'<small>Dastlabki 20 ta so‘z ko‘rsatildi.</small>':''}<div class="buttons"><button type="button" class="btn primary" id="confirm-import">${pending.length} ta so‘zni saqlash</button></div>`:'<p>Yangi so‘z yo‘q. Barcha so‘zlar ushbu to‘plamda mavjud.</p>'}`;
  if($('#confirm-import'))$('#confirm-import').onclick=()=>{if(!pending.length)return;const count=pending.length;for(const row of pending)state.cards.push({...row,id:uid(),reps:0,reviews:0,due:0,ease:2.5,interval:0});pending=[];save();$('#modal').close();render();toast(`${count} ta so‘z saqlandi`);};
 };
}

let reviewLocked=false,reviewTimer=null,reviewCleanup=()=>{};
const gradeNames={again:'Again',hard:'Hard',good:'Good',easy:'Easy'};
const gradeHints={again:'Qayta o‘rganish',hard:'Qiyin esladim',good:'Yaxshi esladim',easy:'Juda oson'};
const gradeDirections={again:'↓',hard:'←',good:'→',easy:'↑'};
const prefs=()=>preferences(state.preferences);
const pronunciation=createPronunciation({getPreferences:prefs,onError:toast,onSource:showAudioSource,onStatus:playing=>document.querySelectorAll('[data-audio]').forEach(b=>b.classList.toggle('audio-playing',playing))});
function showAudioSource(info){const target=$('#audio-source');if(!target)return;target.replaceChildren();if(!info){target.hidden=true;return;}target.hidden=false;const label=document.createElement('span');label.textContent=info.name;target.append(label);for(const [url,text] of [[info.source,'Manba'],[info.license?.url,info.license?.name]]){try{const parsed=new URL(url);if(parsed.protocol!=='https:')continue;const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.textContent=text;target.append(' · ',link);}catch{}}}
function persistReview(){if(session&&classroomUI?.user())session.accountId=classroomUI.user().id;try{sessionStorage.setItem('lexora.study',JSON.stringify(session));}catch{}}
function goStudy(){pronunciation.stop();if(route==='study'){render();window.scrollTo(0,0);}else location.hash='study';}
async function startStudy(deck=''){pronunciation.stop();try{const plan=await classroomUI.revision(),eligible=new Map(plan.queue.map(w=>[w.id,w]));state.cards=state.cards.map(c=>eligible.has(c.id)?{...c,...eligible.get(c.id),word:c.word,deck:c.deck,lessonPending:false}:c);session=newReview(state.cards.filter(c=>eligible.has(c.id)&&(!deck||c.deck===deck)),deck);session.serverRevision=!plan.preview;session.preview=!!plan.preview;session.accountId=classroomUI.user().id;}catch(er){toast(er.message);return;}if(!session.ids.length)session.phase='summary';reviewLocked=false;showBack=false;persistReview();goStudy();}
function studySteps(){return `<div class="study-steps" aria-label="O‘rganish bosqichlari"><span class="${session?.phase==='review'?'current':'complete'}">1 <b>Takrorlash</b></span><i></i><span class="${['test','result'].includes(session?.phase)?'current':''}">2 <b>So‘zlar testi</b></span><i></i><span class="${session?.phase==='result'?'complete':''}">3 <b>Natija</b></span></div>`;}
function study(){if(!session)return `<div class="empty panel"><span class="study-empty-icon">${icon('book')}</span><h1>Takrorlashdan boshlaymiz</h1><p>Avval so‘zlarni eslang. Oxirida aynan shu so‘zlardan variantli va yozma test topshirasiz.</p>${btn('Takrorlashni boshlash','study','primary')}</div>`;if(session.phase==='test')return testView();if(session.phase==='result')return testResult();if(session.phase==='summary'||session.index>=session.ids.length)return reviewSummary();const c=state.cards.find(c=>c.id===session.ids[session.index]);if(!c)return `<div class="notice">Bu so‘z o‘chirilgan. ${btn('Yangi takrorlash','study','primary')}</div>`;const p=prefs();return '<div class="review-minimal-head"><a href="#vocab">← Decklar</a><a href="#settings" aria-label="Takrorlash sozlamalari">⚙</a></div>'+ `<div class="review-workspace"><div class="study-top"><span>${e(c.deck)}</span><span>${session.index+1} / ${session.ids.length}</span></div><div class="progress"><span style="width:${session.index/session.ids.length*100}%"></span></div><div class="review-mode" aria-label="Takrorlash usuli"><button data-review-mode="card" aria-pressed="${!p.writeReview}">Kartochka</button><button data-review-mode="write" aria-pressed="${p.writeReview}">Yozib eslash</button></div><div class="review-card ${showBack?'revealed':''} ${p.motion?'':'no-motion'}" id="review-card" role="group" aria-label="Takrorlash kartochkasi"><span id="swipe-preview" class="swipe-preview" aria-live="polite"></span><div class="card-content"><span class="card-language">${showBack?'INGLIZCHA JAVOB':'O‘ZBEKCHA → INGLIZCHA'}</span>${showBack?`<p class="review-translation">${e(c.translation)}</p><h2 class="review-word">${e(c.word)}</h2><div class="pronunciation">${e(c.ipa||'')}${c.pos?`<span class="tag">${e(c.pos)}</span>`:''}<button class="audio-button" data-audio="${e(c.word)}" aria-label="Inglizcha talaffuzni eshitish">${icon('mic')} Talaffuz</button></div>${session.writeFeedback?`<div class="inline-answer ${session.writeFeedback.correct?'correct':'incorrect'}">${session.writeFeedback.correct?'✓ To‘g‘ri yozdingiz':`Yozganingiz: ${e(session.writeFeedback.answer||'—')} · To‘g‘risi: ${e(c.word)}`}</div>`:''}${c.example?`<p class="review-example">${e(c.example)}<button class="audio-button" data-audio="${e(c.example)}" aria-label="Misol jumlani eshitish">Misolni tinglash</button>${c.exampleUz?`<small>${e(c.exampleUz)}</small>`:''}</p>`:''}<a class="context-link" href="https://youglish.com/pronounce/${encodeURIComponent(c.word)}/english" target="_blank" rel="noopener noreferrer">YouGlish · Kontekstda ko‘rish</a>${c.synonyms?`<div class="rich-detail"><b>Sinonimlar</b><span>${e(c.synonyms)}</span></div>`:''}${c.collocations?`<div class="rich-detail"><b>Collocation</b><span>${e(c.collocations)}</span></div>`:''}`:`<h2 class="review-prompt">${e(c.translation)}</h2>${p.writeReview?`<form id="review-write-form" class="review-write-form"><label class="visually-hidden" for="review-answer">Inglizchasini yozing</label><input id="review-answer" placeholder="Inglizchasini yozing…" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" writingsuggestions="false" required><button class="btn primary">Tekshirish</button></form>`:'<p class="recall-hint">Inglizchasini eslash uchun o‘zingizga vaqt bering.</p>'}`}</div></div>${showBack?`<div class="swipe-guide compact-hidden"><span>↑ Easy</span><div><span>← Hard</span><small>Kartochkani torting</small><span>Good →</span></div><span>↓ Again</span></div><div class="review-grades">${GRADES.map(g=>`<button class="grade-button ${g}" data-grade="${g}"><span class="grade-name">${gradeNames[g]} <kbd>${e(keyLabel(p.keys[g]))}</kbd></span><small>${session.serverRevision?revisionLabel(c,g):g==='again'?'1 daqiqa':schedule(c,g).interval+' kun'}</small></button>`).join('')}</div><p class="answer-hint compact-hidden">${gradeHints.again} · ${gradeHints.hard} · ${gradeHints.good} · ${gradeHints.easy}</p>`:`<button class="btn primary reveal-button" data-action="flip">Javobni ko‘rish <kbd>${e(keyLabel(p.keys.flip))}</kbd></button><p class="answer-hint">Yozib eslash usulini yuqoridan yoqishingiz mumkin.</p>`}</div>`;}
function revealReview(answer){if(!session||session.phase!=='review'||showBack||reviewLocked)return;const c=state.cards.find(c=>c.id===session.ids[session.index]);if(!c)return;if(answer!==undefined)session.writeFeedback={answer,correct:answerMatches(answer,c.word)};showBack=true;render();if(prefs().autoAudio){pronunciation.speak(c.word);}}
async function grade(g){if(!GRADES.includes(g)||!showBack||!session||session.phase!=='review'||reviewLocked||route!=='study')return;const current=session.ids[session.index],idx=state.cards.findIndex(c=>c.id===current);if(idx<0)return;reviewLocked=true;pronunciation.stop();let serverState;if(session.serverRevision){try{serverState=(await classroomUI.reviewWord(current,g,uid())).state;}catch(er){reviewLocked=false;toast(er.message);return;}}state.cards[idx]=serverState?{...state.cards[idx],...serverState}:schedule(state.cards[idx],g);recordReview(session,current,g);delete session.writeFeedback;if(!session.preview)state.log[dateKey()]=(state.log[dateKey()]||0)+1;save();persistReview();const card=$('#review-card');if(card&&prefs().motion){const vectors={again:[0,180],hard:[-220,0],good:[220,0],easy:[0,-180]},[x,y]=vectors[g];card.classList.add('card-leaving');card.style.transform=`translate(${x}px,${y}px) rotate(${x/22}deg)`;card.style.opacity='0';}const committed=session;setTimeout(()=>{if(session!==committed)return;reviewLocked=false;showBack=false;if(route==='study'){render();if(session.phase==='summary')window.scrollTo(0,0);}},prefs().motion?190:0);}
function reviewSummary(){const ids=session.seenIds||[],minutes=Math.max(1,Math.round((Date.now()-session.startedAt)/60000));return `<section class="study-summary panel">${ids.length?`<div class="celebration ${prefs().motion?'':'no-motion'}" aria-hidden="true">${Array.from({length:16},(_,i)=>`<i style="--n:${i}"></i>`).join('')}<span>✓</span></div>`:'<span class="study-empty-icon">'+icon('book')+'</span>'}<span class="eyebrow">TAKRORLASH YAKUNI</span><h1>${ids.length?'So‘zlar takrorlandi!':'Hozircha navbat bo‘sh'}</h1><p>${ids.length?'Endi hozir takrorlagan so‘zlaringizni testda tekshiring.':'Yangi so‘z qo‘shing yoki keyingi takrorlash vaqtida qayting.'}</p>${ids.length?`<div class="summary-metrics"><span><b>${ids.length}</b> ta so‘z</span><span><b>${minutes}</b> daqiqa</span><span>${session.preview?'Namoyish rejimi':'Takrorlash bajarildi'}</span></div><div class="grade-summary">${GRADES.map(g=>`<span class="${g}">${gradeNames[g]} <b>${session.grades[g]||0}</b></span>`).join('')}</div><div class="test-explanation"><b>Keyingi bosqich: yakuniy test</b><p>1. Ma’noga mos inglizcha javobni tanlang.<br>2. Shu so‘zlarning inglizchasini o‘zingiz yozing.</p><p>Test vaqtida boshqa sahifa yoki ilovaga o‘tsangiz, joriy savol xato hisoblanadi.</p></div><button class="btn primary" data-action="review-test">Testni boshlash →</button><button class="btn" data-action="review-repeat">Shu so‘zlarni qaytarish</button>`:''}<a class="text-btn" href="#home">Bosh sahifaga qaytish</a></section>`;}
function startSpell(retry=false){if(!session?.seenIds?.length||!['summary','result'].includes(session.phase)){toast('Test uchun avval so‘zlarni takrorlang.');goStudy();return;}const failed=retry?(session.lessonId?[...session.seenIds]:[...new Set(session.test.answers.filter(a=>!a.correct).map(a=>a.id))]):undefined;if(retry&&!failed.length)return;if(makeTest(session,failed)){session.attemptId=uid();delete session.serverResult;delete session.submitError;persistReview();goStudy();}}
function spell(){return `<section class="panel empty"><h1>Imlo endi takrorlashning bir qismi</h1><p>Kartochkada «Yozib eslash» usulini tanlang yoki takrorlash oxiridagi testni topshiring.</p><button class="btn primary" data-route="study">Takrorlashga o‘tish →</button></section>`;}
function testView(){const t=session.test,c=state.cards.find(c=>c.id===t.ids[t.index]);if(!c)return '<p>So‘z topilmadi. Yangi takrorlashni boshlang.</p>';if(!Array.isArray(t.choices)||!t.choices.includes(c.word))t.choices=testChoices(c,state.cards.filter(card=>t.ids.includes(card.id)));if(t.choices.length<2)t.round='write';const answer=t.answers.find(a=>a.id===c.id&&a.round===t.round),count=t.ids.length,timer=testDuration(c.word,t.round,prefs().testSeconds);return heading('TAKRORLANGAN SO‘ZLARDAN TEST',t.round==='choice'?'So‘zlar testi':'Imlo testi',t.round==='choice'?'Ma’noga mos inglizcha so‘z yoki iborani tanlang.':'O‘zbekcha ma’noga qarab inglizchasini yozing.')+studySteps()+`<section class="test-stage"><div class="test-top"><span>${t.index+1} / ${count}</span><span class="tag">${t.round==='choice'?'1-bosqich · Variantlar':'2-bosqich · Yozma javob'}</span><span id="test-clock" class="test-clock">${timer?timer+' s':'Vaqt cheklanmagan'}</span></div><div class="progress"><span style="width:${t.index/count*100}%"></span></div><div class="test-question"><h2>${e(c.translation)}</h2>${t.round==='choice'?`<div class="test-options">${t.choices.map(w=>`<button class="test-option ${answer&&(w===c.word?'correct':w===answer.answer?'incorrect':'')}" data-test-choice="${e(w)}" ${t.checked?'disabled':''}>${e(w)}</button>`).join('')}</div>`:`<form id="final-test-form"><label class="visually-hidden" for="test-answer">Inglizcha javob</label><input id="test-answer" placeholder="Inglizchasini yozing…" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" writingsuggestions="false" value="${e(answer?.answer||'')}" ${t.checked?'disabled':''} required>${!t.checked?'<button class="btn primary">Javob berish →</button>':''}</form>`}${t.checked?`<div class="test-feedback ${answer.correct?'correct':'incorrect'}" role="status">${answer.correct?'✓ To‘g‘ri javob!':`${answer.reason==='left'?'Test oynasidan chiqildi. ':answer.timeout?'Vaqt tugadi. ':''}To‘g‘ri javob: ${e(c.word)}`}${t.round==='write'&&!answer.correct?`<small>Sizning javobingiz: ${e(answer.answer||'—')}</small>`:''}</div><button class="audio-button" data-audio="${e(c.word)}">${icon('mic')} Talaffuz</button><button class="btn primary next-question" data-action="test-next">${t.index===count-1?(t.round==='choice'?'Imlo testiga o‘tish →':'Natijani ko‘rish →'):'Keyingi savol →'}</button>`:''}</div></section>`;}
function submitTest(answer,timeout=false,reason='',redraw=true){const t=session?.test;if(route!=='study'||session?.phase!=='test'||!t||t.checked)return;const c=state.cards.find(c=>c.id===t.ids[t.index]);if(!c)return;clearInterval(reviewTimer);t.checked=true;const correct=!timeout&&answerMatches(answer,c.word);t.answers.push({id:c.id,round:t.round,answer,correct,timeout,...(reason?{reason}:{})});if(t.round==='write'){state.spell.total++;state.spell.right+=correct?1:0;save();}persistReview();if(redraw)render();if(redraw&&!reason&&prefs().autoAudio)pronunciation.speak(c.word);}
function nextTest(){const t=session?.test;if(!t?.checked)return;pronunciation.stop();t.index++;if(t.index>=t.ids.length){if(t.round==='choice'){t.round='write';t.index=0;}else session.phase='result';}t.checked=false;t.deadline=0;delete t.choices;persistReview();render();if(session.phase==='result'){window.scrollTo(0,0);if(session.lessonId)submitClassResult();}else $('.test-stage')?.scrollIntoView({block:'start'});}
function testResult(){const t=session.test,answers=t.answers,correct=answers.filter(a=>a.correct).length,score=answers.length?Math.floor(correct/answers.length*100):0,wrong=[...new Set(answers.filter(a=>!a.correct).map(a=>a.id))];return `<section class="study-summary panel"><div class="result-score ${score>=80?'passed':''}">${score}<small>%</small></div><span class="eyebrow">YAKUNIY NATIJA</span>${classResultStatus()}<h1>${score>=80?'Ajoyib, davom etamiz!':'Yana bir urinish foydali bo‘ladi'}</h1><p>${correct} / ${answers.length} ta javob to‘g‘ri · O‘tish uchun kamida 80%</p><div class="summary-metrics">${answers.some(a=>a.round==='choice')?`<span>Variantlar <b>${answers.filter(a=>a.round==='choice'&&a.correct).length}/${answers.filter(a=>a.round==='choice').length}</b></span>`:''}<span>Imlo <b>${answers.filter(a=>a.round==='write'&&a.correct).length}/${answers.filter(a=>a.round==='write').length}</b></span></div><div class="test-result-list">${t.ids.map(id=>{const c=state.cards.find(c=>c.id===id);if(!c)return '';const choice=answers.find(a=>a.id===id&&a.round==='choice'),write=answers.find(a=>a.id===id&&a.round==='write');return `<div><span><b>${e(c.word)}</b><small>${e(c.translation)}</small></span><span>${choice?`<span class="${choice.correct?'correct':'incorrect'}">Tanlash ${choice.correct?'✓':'×'}</span>`:''}<span class="${write?.correct?'correct':'incorrect'}">Imlo ${write?.correct?'✓':'×'}</span></span></div>`;}).join('')}</div><div class="buttons">${wrong.length?`<button class="btn primary" data-action="test-retry">${session.lessonId?'To‘liq testni qayta topshirish →':'Xatolarni qayta ishlash →'}</button>`:''}<button class="btn" data-action="review-repeat">Shu so‘zlarni qaytarish</button><a class="btn" href="#home">Bosh sahifa</a></div><p class="answer-hint">XP tekshirilgan dars natijasi va kunlik bosqichlar uchun beriladi.</p></section>`;}
function repeatReview(){if(!session?.seenIds?.length)return;const ids=[...session.seenIds],deck=session.deck,lessonId=session.lessonId,preview=session.preview;session=newReview(ids.map(id=>state.cards.find(c=>c.id===id)).filter(Boolean),deck);if(lessonId)session.lessonId=lessonId;session.preview=preview;showBack=false;persistReview();goStudy();}
function mountReview(){if(route!=='study'||!session)return;if(session.phase==='review'){
 $('#review-write-form')?.addEventListener('submit',ev=>{ev.preventDefault();revealReview($('#review-answer').value);});
 document.querySelectorAll('[data-review-mode]').forEach(b=>b.onclick=()=>{state.preferences={...prefs(),writeReview:b.dataset.reviewMode==='write'};showBack=false;delete session.writeFeedback;pronunciation.stop();save();render();});
 const card=$('#review-card');if(!card)return;let drag=null,moved=false;
 const reset=()=>{drag=null;card.classList.remove('is-dragging');card.style.transform='';card.style.opacity='';const hint=$('#swipe-preview');if(hint){hint.textContent='';hint.className='swipe-preview';}};
 card.addEventListener('pointerdown',ev=>{if(!ev.isPrimary||ev.button!==0||ev.target.closest('input,button,a,form')||reviewLocked)return;drag={id:ev.pointerId,x:ev.clientX,y:ev.clientY,dx:0,dy:0};moved=false;card.setPointerCapture(ev.pointerId);});
 card.addEventListener('pointermove',ev=>{if(!drag||drag.id!==ev.pointerId)return;drag.dx=ev.clientX-drag.x;drag.dy=ev.clientY-drag.y;if(Math.max(Math.abs(drag.dx),Math.abs(drag.dy))>8)moved=true;if(!moved)return;card.classList.add('is-dragging');card.style.transform=`translate(${drag.dx}px,${drag.dy}px) rotate(${Math.max(-12,Math.min(12,drag.dx/18))}deg)`;const g=swipeGrade(drag.dx,drag.dy,25),hint=$('#swipe-preview');hint.textContent=showBack&&g?gradeDirections[g]+' '+gradeNames[g]:'Avval javobni oching';hint.className='swipe-preview visible '+(g||'');});
 card.addEventListener('pointerup',ev=>{if(!drag||drag.id!==ev.pointerId)return;const g=swipeGrade(drag.dx,drag.dy);if(card.hasPointerCapture?.(ev.pointerId))card.releasePointerCapture(ev.pointerId);reset();if(g&&showBack)grade(g);else if(g&&!showBack)toast('Baholashdan oldin javobni oching.');else if(!moved&&!showBack&&!prefs().writeReview)revealReview();});
 card.addEventListener('pointercancel',reset);card.addEventListener('lostpointercapture',()=>{if(drag)reset();});
 reviewCleanup=()=>{drag=null;};
 }else if(session.phase==='test'){
  const releaseInput=protectTestInput(!session.test.checked?$('#test-answer'):null);
  const releaseExit=!session.test.checked?watchTestExit(document,window,()=>submitTest('',true,'left',!document.hidden),()=>{if(route==='study'&&session?.phase==='test')render();}):()=>{};
  reviewCleanup=()=>{releaseInput();releaseExit();};
  $('#final-test-form')?.addEventListener('submit',ev=>{ev.preventDefault();submitTest($('#test-answer').value);});
  const t=session.test,p=prefs();if(!t.checked&&p.testSeconds){if(!t.deadline){const card=state.cards.find(c=>c.id===t.ids[t.index]);t.deadline=Date.now()+testDuration(card?.word,t.round,p.testSeconds)*1000;}persistReview();const tick=()=>{if(session?.test!==t||session.phase!=='test'||route!=='study'){clearInterval(reviewTimer);return;}const left=Math.max(0,Math.ceil((t.deadline-Date.now())/1000));if($('#test-clock')){$('#test-clock').textContent=left+' s';$('#test-clock').classList.toggle('running-low',left<=5);}if(!left)submitTest('',true);};reviewTimer=setInterval(tick,250);tick();}
 }
}
function cleanupReview(){clearInterval(reviewTimer);reviewCleanup();reviewCleanup=()=>{};}
function reviewSettings(){const p=prefs(),voices=pronunciation.voices();return `<section class="panel review-settings"><h2>Takrorlashni o‘zingizga moslang</h2><form id="review-settings-form"><div class="form-grid"><label>Talaffuz aksenti<select name="accent"><option value="en-US" ${p.accent==='en-US'?'selected':''}>English · US</option><option value="en-GB" ${p.accent==='en-GB'?'selected':''}>English · UK</option></select></label><label>Inglizcha ovoz<select name="voiceURI" id="english-voice"><option value="">Avtomatik: tanlangan aksent</option>${voices.map(v=>`<option value="${e(v.voiceURI)}" ${v.voiceURI===p.voiceURI?'selected':''}>${e(v.name)} · ${e(v.lang)}</option>`).join('')}</select></label><label>Talaffuz tezligi<select name="rate">${[.6,.8,1,1.2].map(rate=>`<option value="${rate}" ${p.rate===rate?'selected':''}>${rate}×</option>`).join('')}</select></label><label>Test vaqti<select name="testSeconds">${[15,30,0].map(s=>`<option value="${s}" ${p.testSeconds===s?'selected':''}>${s===15?'Moslashuvchan · odatiy':s===30?'Moslashuvchan · ko‘proq vaqt':'Vaqtsiz'}</option>`).join('')}</select></label></div><p class="settings-help">Vaqt javobdagi harflar va so‘zlar soniga qarab belgilanadi. Imlo uchun variantli testdan ko‘proq vaqt beriladi.</p><div class="settings-checks"><label><input type="checkbox" name="autoAudio" ${p.autoAudio?'checked':''}> Javob ochilganda inglizchasini avtomatik aytish</label><label><input type="checkbox" name="writeReview" ${p.writeReview?'checked':''}> Kartochkada inglizchasini yozib eslash</label><label><input type="checkbox" name="motion" ${p.motion?'checked':''}> Kartochka animatsiyalari va yakun effektlari</label></div><h3>Klaviatura tugmalari</h3><p class="settings-help">Maydonni tanlab kerakli tugmani bosing. Har amal uchun alohida tugma tanlang.</p><div class="key-grid">${[...GRADES,'flip'].map(g=>`<label>${g==='flip'?'Javobni ochish':gradeNames[g]}<input class="shortcut-input" name="key-${g}" value="${e(keyLabel(p.keys[g]))}" data-key="${e(p.keys[g])}" readonly aria-label="${g==='flip'?'Javobni ochish':gradeNames[g]} tugmasi"></label>`).join('')}</div><p class="settings-help">Surish: ↑ Easy · ↓ Again · ← Hard · → Good. Sichqoncha va sensor ekran uchun.</p><div class="error" id="preferences-error" role="status"></div><div class="buttons"><button class="btn primary">Boshqaruvni saqlash</button><button class="btn" type="button" data-action="keys-reset">Standart tugmalar</button><button class="btn" type="button" data-action="voice-preview">Ovozni sinash</button></div><small>Inglizcha ovoz bo‘lmasa, so‘zlar uchun lug‘atdagi asl audio yozuv ishlatiladi. Iboralar uchun qurilmada English ovozi kerak bo‘lishi mumkin.</small></form></section>`;}
function mountReviewSettings(){const form=$('#review-settings-form');if(!form)return;form.querySelectorAll('.shortcut-input').forEach(input=>input.onkeydown=ev=>{if(ev.key==='Tab')return;ev.preventDefault();if(ev.ctrlKey||ev.metaKey||ev.altKey||['Shift','Control','Alt','Meta','Escape'].includes(ev.key))return;input.dataset.key=inputKey(ev);input.value=keyLabel(input.dataset.key);});form.onsubmit=ev=>{ev.preventDefault();const data=new FormData(form),keys=Object.fromEntries([...GRADES,'flip'].map(g=>[g,form.querySelector(`[name="key-${g}"]`).dataset.key]));if(new Set(Object.values(keys)).size!==5){$('#preferences-error').textContent='Bitta tugmani bir nechta amalga berib bo‘lmaydi.';return;}state.preferences=preferences({keys,accent:data.get('accent'),voiceURI:data.get('voiceURI'),rate:Number(data.get('rate')),testSeconds:Number(data.get('testSeconds')),autoAudio:data.has('autoAudio'),writeReview:data.has('writeReview'),motion:data.has('motion')});save();toast('Takrorlash sozlamalari saqlandi');render();};}

const lessons=[{id:'context',title:'So‘zni kontekstda o‘rganish',tag:'LUG‘AT · 3 DAQIQA',text:'Yangi so‘zni yakka holda emas, jumlada o‘rganing. «Resilient» — qiyinchilikdan keyin tiklana oladigan. Masalan: “She remained resilient after the setback.” O‘zingizga tegishli bitta misol yozish so‘z bilan shaxsiy bog‘lanish yaratadi.',question:'Qaysi misolda “resilient” to‘g‘ri ishlatilgan?',answers:['She remained resilient after the setback.','She resilient to school yesterday.','I have two resilient.'],correct:0},{id:'collocations',title:'Birga ishlatiladigan so‘zlar',tag:'B2 · 4 DAQIQA',text:'Ingliz tilida ayrim so‘zlar tabiiy juftlik hosil qiladi. Masalan, “make a decision” (qaror qilmoq), “conduct research” (tadqiqot o‘tkazmoq) va “draw a conclusion” (xulosa chiqarmoq). Bularni to‘liq ibora sifatida kartochkaga yozing.',question:'“Qaror qilmoq” uchun to‘g‘ri birikmani tanlang.',answers:['do a decision','make a decision','take research'],correct:1},{id:'review',title:'Takrorlashni odatga aylantirish',tag:'SRS · 2 DAQIQA',text:'Takrorlash paytida avval javobni mustaqil eslashga harakat qiling. So‘ng inglizcha javobni ochib baholang. “Yana” — eslay olmadim; “Qiyin” — zo‘rg‘a esladim; “Yaxshi” — esladim; “Oson” — darhol esladim. Bahoni rost qo‘yish keyingi intervalni moslashtiradi.',question:'Javobni eslay olmasangiz qaysi bahoni tanlaysiz?',answers:['Oson','Yaxshi','Yana'],correct:2}];
function courses(){return heading('QISQA DARSLAR','O‘rganish usullari','Lug‘at o‘rganish usullari bo‘yicha qisqa darslar va bitta savol.')+`<div class="cards">${lessons.map((l,i)=>`<button class="link-card" style="text-align:left" data-lesson="${l.id}"><span class="eyebrow">${l.tag}</span><div style="font-size:42px;color:var(--purple);margin:25px 0">0${i+1}</div><h3>${l.title}</h3><p>${state.completed.includes(l.id)?'✓ Tugallangan':'O‘qish va mashq qilish →'}</p></button>`).join('')}</div><div class="notice">Bu boshlang‘ich mini darslar. To‘liq CEFR kurslari va o‘qituvchi darslari uchun kontent hali qo‘shilmagan.</div>`;}
function lesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;openModal(l.title,`<p class="lesson-text">${l.text}</p><h3>${l.question}</h3><form id="quiz">${l.answers.map((a,i)=>`<label style="display:block;padding:10px 0"><input type="radio" name="answer" value="${i}" required> ${e(a)}</label>`).join('')}<div class="result" id="quiz-result"></div><button class="btn primary">Tekshirish</button></form>`);$('#quiz').onsubmit=ev=>{ev.preventDefault();const correct=Number(new FormData(ev.target).get('answer'))===l.correct;$('#quiz-result').textContent=correct?'To‘g‘ri! Dars tugallandi.':'Hali to‘g‘ri emas. Matnni qayta o‘qib ko‘ring.';if(correct&&!state.completed.includes(id)){state.completed.push(id);save();render();}};}
function analytics(){const history=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {date:d,n:state.log[dateKey(d)]||0};}),max=Math.max(1,...history.map(x=>x.n));return heading('O‘QUV FAOLLIGI','Natijalar','Haqiqiy mashqlaringiz asosida hisoblangan shaxsiy natijalar.')+`<div class="stats">${stat('ϟ',state.xp,'Jami XP')}${stat('↻',Object.values(state.log).reduce((a,b)=>a+b,0),'Takrorlangan kartochkalar')}${stat('⌨',state.spell.total?Math.round(state.spell.right/state.spell.total*100)+'%':'—','Imlo aniqligi')}${stat('♨',streak(state.log),'Ketma-ket kunlar')}</div><div class="grid"><section class="panel"><h2>Oxirgi 7 kun</h2><p style="font-size:11px">Kuniga takrorlangan kartochkalar soni</p><div class="chart">${history.map(h=>`<div class="bar-wrap"><span>${h.n}</span><div class="bar" style="height:${h.n/max*125}px"></div><span>${shortDate(h.date)}</span></div>`).join('')}</div></section><section class="panel"><h2>To‘plamlar bo‘yicha</h2>${decks().map(d=>{const cs=state.cards.filter(c=>c.deck===d),n=cs.filter(c=>c.reps>0).length;return `<div style="margin-top:22px"><div class="goal-row"><span>${e(d)}</span><b>${n} / ${cs.length}</b></div><div class="progress"><span style="width:${cs.length?n/cs.length*100:0}%"></span></div></div>`;}).join('')}</section></div><div class="notice">Bu yerda shu qurilmadagi shaxsiy mashqlar ko‘rsatilgan. Guruh topshiriqlarining yakuniy natijalari ustozingizning Samaradorlik bo‘limida saqlanadi.</div>`;}
function telegram(){return heading('BIRGA O‘RGANISH','Guruhlar','Ustoz materiallari va topshiriqlari uchun umumiy maydon.')+`<div class="grid"><section class="panel"><span class="eyebrow">ULANISH HOLATI</span><h2>Guruhlar keyingi bosqichda ulanadi.</h2><p>Ustoz guruh yaratib, sizga qo‘shilish kodini beradi. Telegram’da ro‘yxatdan o‘tganingizdan so‘ng shu kod bilan guruhga kirasiz.</p><div class="notice">Bu sinov nusxasida guruhga qo‘shilish hali faol emas. Hozirgi mashqlar shaxsiy brauzeringizda saqlanadi.</div><a class="btn" href="https://t.me/lexora_academy_bot" target="_blank" rel="noopener">Lexora botini ochish ↗</a><small>Bot ochilgan, platformaga ulanishi hali yakunlanmagan.</small></section><section class="panel"><h2>Guruhda nimalar bo‘ladi?</h2>${['Ustoz tayyorlagan lug‘at va dars materiallari','Muddatli yozma va og‘zaki topshiriqlar','Javoblar uchun ustoz fikri va qayta topshirish','Guruh ichidagi natijalar va topshiriq bo‘yicha XP'].map((t,i)=>`<div class="lesson-item"><span style="color:var(--muted);margin-right:12px">0${i+1}</span>${t}</div>`).join('')}</section></div>`;}
let designs=[];
async function loadDesigns(){try{designs=await (await fetch('designs.json')).json();if(route==='designs')render();}catch{}}
function designView(){return heading('SIZ YUBORGAN STITCH MANBALARI','Dizaynlar kutubxonasi','Asl ekranlar taqqoslash uchun saqlandi. Ular alohida dizayn namunalari.')+`<div class="cards">${designs.map(d=>`<a class="link-card" href="${e(d.path)}" target="_blank" rel="noopener"><img src="${e(d.image)}" alt="${e(d.name)}" loading="lazy"><h3>${e(d.name)}</h3><span class="text-btn">Asl ekran ↗</span></a>`).join('')}</div>`;}
function settings(){return heading('O‘ZINGIZGA MOSLANG','Sozlamalar','Profil, kunlik maqsad va ma’lumotlaringiz.')+`<div class="settings-grid"><section class="panel"><h2>Shaxsiy sozlamalar</h2><form id="settings-form"><label>Ismingiz<input name="name" value="${e(state.name)}" maxlength="40" required></label><label>Kunlik maqsad (kartochka)<input name="goal" type="number" value="${state.goal}" min="1" max="500" required></label><button class="btn primary">Saqlash</button></form></section><section class="panel"><h2>Ma’lumotlar va hisob</h2><p>Guruhlar, darslar, yo‘qlama va topshirilgan testlar serverda saqlanadi. Kundalik revision serverda saqlanadi. XP va ovoz sozlamalari shu brauzerga tegishli; speaking yozuvini yuklab saqlang.</p><div class="buttons">${btn('↓ Zaxira nusxasi','export')}${classroomUI.provider()==='telegram'?'<button class="btn" data-class-action="logout">Hisobdan chiqish</button>':'<a class="btn" href="/signout-with-chatgpt?return_to=%2F" target="_top">Hisobdan chiqish</a>'}</div><p class="callout">${storageOK?'Brauzer xotirasiga saqlash faol.':'Saqlashda muammo bor. Zaxira oling.'}</p></section></div>${reviewSettings()}<div class="notice">Guruhlar va rollar ulangan. Kirish: ${classroomUI.provider()==='telegram'?'Telegram':'ChatGPT'}. Google kirishi hali ulanmagan. Vazifa qoralamasi uchun AI o‘qituvchi oynasida mavjud.</div>`;}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`lexora-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function restore(){toast('Guruhdagi so‘zlar serverdan olinadi. Shaxsiy zaxirani hozir almashtirib bo‘lmaydi.');return; openModal('Zaxira nusxasini tiklash','<p>Lexora JSON zaxirasini tanlang. Tiklash joriy so‘zlar va natijalarni almashtiradi.</p><input type="file" id="backup-file" accept=".json"><p id="backup-result" class="error"></p>');$('#backup-file').onchange=async ev=>{$('#backup-confirm')?.remove();try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Fayl juda katta.');const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.cards)||data.cards.length>10000||typeof data.name!=='string'||!Number.isFinite(data.goal)||data.goal<1||data.goal>500||!Number.isFinite(data.xp)||data.xp<0||!data.log||!data.spell||!Array.isArray(data.completed))throw Error('Lexora zaxirasi formati noto‘g‘ri.');const ids=new Set();for(const c of data.cards){if(typeof c.id!=='string'||ids.has(c.id)||!['word','translation','deck','level','example'].every(k=>typeof c[k]==='string')||!['due','reps','reviews','interval','ease'].every(k=>Number.isFinite(c[k])&&c[k]>=0))throw Error('Kartochkalar formati noto‘g‘ri.');ids.add(c.id);}if(data.deckNames&&(!Array.isArray(data.deckNames)||data.deckNames.some(d=>typeof d!=='string'||d.length>80)))throw Error('To‘plamlar formati noto‘g‘ri.');if(Object.values(data.log).some(v=>!Number.isInteger(v)||v<0)||!Number.isInteger(data.spell.right)||!Number.isInteger(data.spell.total)||data.spell.right<0||data.spell.total<data.spell.right)throw Error('Statistika formati noto‘g‘ri.');$('#backup-result').className='success';$('#backup-result').textContent=`${data.cards.length} ta so‘z topildi.`;const b=document.createElement('button');b.id='backup-confirm';b.className='btn primary';b.textContent='Tasdiqlash va tiklash';b.onclick=()=>{state=data;session=null;try{sessionStorage.removeItem('lexora.study');}catch{}save();$('#modal').close();render();toast('Zaxira tiklandi');};$('#modal-body').append(b);}catch(err){$('#backup-result').textContent=err.message;}};}
function render(){document.body.classList.toggle('focus-review',route==='study');cleanupReview();const classView=classroomUI.view(route),currentNav=classroomUI.nav();if(route!=='speaking')leaveSpeaking();leaveSkills();const pages={watch:()=>skillsView('watch'),reading:()=>skillsView('reading'),listening:()=>skillsView('listening'),writing:()=>skillsView('writing'),home,tasks,vocab,study,spell,speaking:speakingView,courses,analytics,telegram,settings};$('#app').innerHTML=classView??(pages[route]||home)();document.body.classList.toggle('public-view',!!$('#public-landing'));$('#page-name').textContent=currentNav.find(n=>n[0]===route)?.[2]||(route.startsWith('group/')?'Guruh':route==='study'?'Takrorlash':'Bosh sahifa');$('#nav').innerHTML=currentNav.map(([id,icon,title,badge])=>`<a href="#${id}" class="${route===id||route==='study'&&id==='vocab'||route.startsWith('group/')&&id==='groups'?'active':''}" ${route===id?'aria-current="page"':''}><span class="icon">${windowIcon(icon)}</span>${title}${badge?`<span class="badge">${badge}</span>`:''}</a>`).join('');updateHeader();classroomUI.mount();if(classView!==null)return;if(route==='speaking')mountSpeaking();if(['reading','listening','writing','watch'].includes(route))mountSkills(route,classroomUI.user()?.id);if(route==='vocab'){classroomUI.revision().then(plan=>{const el=$('#revision-overview');if(!el)return;if(plan.preview){el.innerHTML='<p>Namoyish rejimi · '+plan.queue.length+' ta so‘z. O‘quvchilarning revision rejasi o‘zgarmaydi.</p>';return;}const fresh=plan.queue.filter(w=>!w.phase).length,learning=plan.queue.filter(w=>w.phase==='learning').length,reviews=plan.queue.length-fresh-learning;el.innerHTML='<div><b>'+fresh+'</b><small>Yangi</small></div><div><b>'+learning+'</b><small>O‘rganilmoqda</small></div><div><b>'+reviews+'</b><small>Takrorlash</small></div><p>'+plan.summaries.reduce((n,g)=>n+g.done,0)+' ta so‘z bugun qaytarildi · '+plan.queue.length+' ta hozir tayyor</p>';}).catch(er=>{if($('#revision-overview'))$('#revision-overview').textContent=er.message;});classroomUI.competition().then(data=>{const el=$('#competition');if(!el)return;el.innerHTML=data.boards.map(g=>'<section><h3>'+e(g.name)+'</h3><ol class="ranking-list">'+g.rows.map(r=>'<li class="'+(r.id===classroomUI.user()?.id?'is-me':'')+'"><span>'+r.rank+'</span><b>'+e(r.name)+'</b><strong>'+r.xp+' XP</strong></li>').join('')+'</ol>'+(g.rows.length?'':'<p>Hali o‘quvchilar yo‘q.</p>')+'</section>').join('')||'<p>Guruhga qo‘shilgach reyting ochiladi.</p>';if(!classroomUI.teacher()){state.xp=data.boards.reduce((n,g)=>n+(g.rows.find(r=>r.id===classroomUI.user()?.id)?.xp||0),0);updateHeader();}}).catch(er=>{if($('#competition'))$('#competition').textContent=er.message;});$('#search').oninput=ev=>{search=ev.target.value;$('#word-table').innerHTML=wordTable();};$('#deck-filter').onchange=ev=>{deckFilter=ev.target.value;$('#word-table').innerHTML=wordTable();};}mountReview();if(route==='settings')mountReviewSettings();if(route==='settings')$('#settings-form').onsubmit=async ev=>{ev.preventDefault();const data=new FormData(ev.target),name=String(data.get('name')).trim();if(!name)return;try{await classroomUI.updateProfile(name);state.name=name;state.goal=Number(data.get('goal'));save();toast('Sozlamalar saqlandi');render();}catch(er){toast(er.message);}};}

let submittingClass=false;
const classroomUI=createClassroom({escape:e,redraw:()=>render(),notify:toast,onAccount:syncClassAccount,onLibrary:syncClassLibrary,onLesson:startClassLesson});
function syncClassAccount(user){const key='lexora.classroom.'+user.id;if(storageKey!==key){storageKey=key;try{state=JSON.parse(localStorage.getItem(key)||'null')||blank();if(!Array.isArray(state.cards)||!state.log||!state.spell)state=blank();}catch{state=blank();}session=null;}state.name=user.name;}
function syncClassLibrary(words,user,changed){
 const nextKey='lexora.classroom.'+user.id;
 if(storageKey!==nextKey){storageKey=nextKey;try{state=JSON.parse(localStorage.getItem(storageKey)||'null')||blank();if(!Array.isArray(state.cards))state=blank();}catch{state=blank();}session=null;}
 state.name=user.name;const old=new Map(state.cards.map(c=>[c.id,c]));
 state.cards=words.map(w=>({...old.get(w.id),id:w.id,word:w.word,translation:w.translation,example:w.example,level:'',deck:w.groupName+' · '+w.deckName,lessonId:w.lesson_id,lessonPending:!w.passedAt,due:w.revisionState?.due??old.get(w.id)?.due??0,reps:w.revisionState?.reps??old.get(w.id)?.reps??0,reviews:old.get(w.id)?.reviews||0,interval:old.get(w.id)?.interval||0,ease:old.get(w.id)?.ease||2.5,...(w.revisionState||{})}));
 if(!session)try{const stored=JSON.parse(sessionStorage.getItem('lexora.study')||'null');if(stored?.accountId===user.id)session=restoreReview(stored,state.cards);}catch{}
 save();
}
function startClassLesson(l,words){for(const w of words)if(!state.cards.some(c=>c.id===w.id))state.cards.push({...w,deck:l.title,due:0,reps:0});session=newReview(words.map(w=>state.cards.find(c=>c.id===w.id)).filter(Boolean),l.title);session.preview=classroomUI.teacher();session.lessonId=l.id;session.accountId=classroomUI.user().id;showBack=false;reviewLocked=false;persistReview();goStudy();}
function classResultStatus(){if(!session?.lessonId)return '';if(session.preview)return '<div class="notice">Namoyish rejimi. Bu mashq o‘quvchilar natijasi va reytingiga ta’sir qilmaydi.</div>';if(submittingClass)return '<div class="class-test-status" role="status">Natija serverga saqlanmoqda…</div>';if(session.serverResult)return '<div class="class-test-status '+(session.serverResult.passed?'passed':'')+'">'+(session.serverResult.passed?(session.serverResult.lessonCompleted===false?'✓ Bugungi qism topshirildi. Keyingi so‘zlar shaxsiy rejangizga ko‘ra ochiladi.':'✓ Dars topshirildi. So‘zlar o‘qituvchi tanlagan deckingizga qo‘shildi.'):'Testdan o‘tish uchun kamida 80% kerak. Dars hali topshirilmagan; to‘liq testni qayta ishlang.')+'</div>';return '<div class="class-test-status">'+e(session.submitError||'Natijani serverga yuboring.')+' <button class="btn" data-action="class-submit">Natijani yuborish</button></div>';}
async function submitClassResult(){if(submittingClass||!session?.lessonId||session.phase!=='result'||session.serverResult)return;const current=session;submittingClass=true;render();try{const result=await classroomUI.submit(current.lessonId,current.test.answers,current.attemptId||(current.attemptId=uid()));current.serverResult=result;delete current.submitError;}catch(er){current.submitError=er.message;}finally{submittingClass=false;persistReview();render();}}

document.addEventListener('click',ev=>{const t=ev.target.closest('button,a');if(!t)return;if(!classroomUI.ready()&&!t.dataset.classAction&&!t.dataset.classRole&&!t.dataset.classApprove){return;}if(t.dataset.route){location.hash=t.dataset.route;}if(t.dataset.study!==undefined){startStudy(t.dataset.study);}if(t.dataset.edit)addModal(t.dataset.edit);if(t.dataset.delete){const c=state.cards.find(c=>c.id===t.dataset.delete);openModal('So‘zni o‘chirish',`<p>«${e(c.word)}» so‘zini o‘chirasizmi?</p><button class="btn danger" id="confirm-delete">O‘chirish</button>`);$('#confirm-delete').onclick=()=>{state.cards=state.cards.filter(x=>x.id!==c.id);save();$('#modal').close();render();};}if(t.dataset.audio)pronunciation.speak(t.dataset.audio);if(t.dataset.testChoice!==undefined)submitTest(t.dataset.testChoice);if(t.dataset.grade)grade(t.dataset.grade);if(t.dataset.lesson)lesson(t.dataset.lesson);const actions={'class-submit':submitClassResult,'deck-add':deckModal,add:()=>addModal(),import:importModal,close:()=>$('#modal').close(),study:()=>startStudy(),flip:()=>revealReview(),'review-test':()=>startSpell(),'review-repeat':repeatReview,'test-next':nextTest,'test-retry':()=>startSpell(true),'voice-preview':()=>{const form=$('#review-settings-form');if(form)pronunciation.speak(pronunciation.voices().length?'Hello. Welcome to Lexora.':'welcome',{accent:form.elements.accent.value,voiceURI:form.elements.voiceURI.value,rate:Number(form.elements.rate.value)});},'keys-reset':()=>{const form=$('#review-settings-form');if(form)Object.entries(preferences().keys).forEach(([g,key])=>{const el=form.querySelector(`[name="key-${g}"]`);el.dataset.key=key;el.value=keyLabel(key);});},'spell-start':()=>startSpell(),export:exportData,restore,home:()=>location.hash='home',vocab:()=>location.hash='vocab'};actions[t.dataset.action]?.();});
document.addEventListener('keydown',ev=>{if(ev.repeat||ev.ctrlKey||ev.metaKey||ev.altKey||$('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(route==='study'&&session?.phase==='review'){const key=inputKey(ev),p=prefs();if(key===p.keys.flip&&!showBack){ev.preventDefault();revealReview();}else if(showBack){const g=GRADES.find(g=>p.keys[g]===key);if(g){ev.preventDefault();grade(g);}}}});

function closeMenu(){$('.sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}
$('#back-nav').onclick=()=>{const previous=trail.pop();location.hash=previous||((route==='study')?'vocab':'home');lastRoute='';};
$('#theme-toggle').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-toggle').textContent=dark?'Ochiq rejim':'Tungi rejim';try{localStorage.setItem('lexora.theme',dark?'dark':'light');}catch{}};
$('#menu').onclick=()=>{const opened=$('.sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(opened));};$('#close-menu').onclick=closeMenu;document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu();});document.querySelector('.sidebar').addEventListener('click',ev=>{if(ev.target.closest('a'))closeMenu();});document.addEventListener('click',ev=>{if(!ev.target.closest('.sidebar')&&!ev.target.closest('#menu'))closeMenu();});
window.addEventListener('hashchange',()=>{pronunciation.stop();const next=location.hash.slice(1)||'home';if(route==='study'&&next!=='study'&&session?.phase==='test'&&!session.test.checked)submitTest('',true,'left',false);if(lastRoute&&route!==next)trail.push(route);lastRoute=next;route=next;closeMenu();render();window.scrollTo(0,0);});
window.speechSynthesis?.addEventListener('voiceschanged',()=>{const select=$('#english-voice');if(!select)return;const selected=select.value;select.innerHTML='<option value="">Avtomatik: tanlangan aksent</option>'+pronunciation.voices().map(v=>'<option value="'+e(v.voiceURI)+'">'+e(v.name)+' · '+e(v.lang)+'</option>').join('');select.value=selected;});
window.addEventListener('pagehide',()=>pronunciation.stop());
route=location.hash.slice(1)||'home';render();classroomUI.boot();
